from collections import deque

def countOfNodes(graph, n):
    if n == 1:
        return 0

    count = 0
    visited = [False] * n
    q = deque()
    q.append(0)
    visited[0] = True
    level = [0] * n

    while q:
        u = q.popleft()
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                level[v] = level[u] + 1
                q.append(v)

    even = 0
    odd = 0
    for i in range(n):
        if level[i] % 2 == 0:
            even += 1
        else:
            odd += 1

    return even * odd
